const { EventHubProducerClient } = require("@azure/event-hubs");

const producer = new EventHubProducerClient(connectionString, eventHubName);

const batch = await producer.createBatch();

for (const device of devices) {
  const event = {
    body: JSON.stringify({ temperature: device.temp, timestamp: Date.now() }),
    partitionKey: device.id  // Same device = same partition
  };
  batch.tryAdd(event);
}

await producer.sendBatch(batch);
await producer.close();

const { EventHubConsumerClient } = require("@azure/event-hubs");

const consumer = new EventHubConsumerClient(
  "$Default", // consumer group
  connectionString,
  eventHubName
);

const subscription = consumer.subscribe({
  async processEvents(events, context) {
    for (const event of events) {
      console.log(`Partition: ${context.partitionId}, Offset: ${event.offset}`);
      console.log(`Body: ${event.body}`);
    }
  },
  async processError(context, error) {
    console.error("Error:", error);
  }
});
